/// Sample 30-day rate history (22K gold / silver per gram).
List<List<num>> rateHistory({bool silver = false, int days = 30}) {
  final out = <List<num>>[];
  for (var i = days - 1; i >= 0; i--) {
    final t = days - 1 - i;
    final g = 13400 + (t * 4.2) + ((t * 37) % 23) - 11;
    final s = 228 + (t * 0.4) + ((t * 13) % 7) * 0.5;
    out.add([i, silver ? double.parse(s.toStringAsFixed(2)) : g.round()]);
  }
  return out;
}
